imports:
# Educational tasks record anonymous session results, without diagnostic interpretation.
import csv
import random
import time
from datetime import datetime

def lab_cancel(app):
    app.generation += 1; app.phase = 'idle'
    if app.timer is not None:
        app.root.after_cancel(app.timer); app.timer = None

def lab_memory_hide(app,generation):
    if generation != app.generation or app.phase != 'showing':
        return
    app.timer = None; app.Board.delete('all'); app.phase = 'answer'; app.started = time.monotonic()
    app.Board.create_text(460,150,text='Type the sequence, then Submit.',font=('TkDefaultFont',20))
    app.Feedback.configure(text='The sequence is hidden. Type your answer now; response timing has started.')
    app.Answer.focus_set()

def lab_start(app):
    lab_cancel(app); app.trial_mode = app.Mode.get(); app.Answer.delete(0,'end'); app.Board.delete('all')
    app.trial_level = app.levels[app.trial_mode]
    if app.trial_mode == 'Memory':
        app.expected = ''.join(str(random.randrange(10)) for _ in range(app.trial_level)); app.phase = 'showing'
        app.Board.create_text(460,150,text=' '.join(app.expected),font=('TkDefaultFont',34,'bold'))
        app.Feedback.configure(text=f'Remember {app.trial_level} digits. The answer box activates when they disappear.')
        generation = app.generation; app.timer = app.root.after(1200+app.trial_level*250,lambda:lab_memory_hide(app,generation))
    else:
        app.phase = 'search'; app.target = random.randrange(36); app.started = time.monotonic()
        for i in range(36):
            x = 220+(i%6)*75; y = 20+(i//6)*50
            app.Board.create_rectangle(x,y,x+65,y+42,fill='#edf3fb',outline='#b2bfd0')
            app.Board.create_text(x+32,y+21,text='O' if i==app.target else 'Q',font=('TkDefaultFont',20))
        app.Feedback.configure(text='Find and click the single O among the Q characters.')

def lab_finish(app, correct):
    if app.phase not in ('answer','search'):
        return
    elapsed = max(0,time.monotonic()-app.started)
    record = {'timestamp':datetime.now().isoformat(timespec='seconds'),'mode':app.trial_mode,'level':app.trial_level,'correct':bool(correct),'response_ms':round(elapsed*1000,1)}
    app.results.append(record); app.results = app.results[-200:]; app.phase = 'finished'
    if app.trial_mode == 'Memory':
        app.levels['Memory'] = max(2,min(9,app.trial_level+(1 if correct else -1)))
    app.Feedback.configure(text=('Correct' if correct else 'Try again')+f' | Response {record["response_ms"]:.0f} ms | Press Start trial for another round.')
    lab_plot(app)

def lab_submit(app):
    if app.phase == 'answer':
        lab_finish(app,''.join(app.Answer.get().split())==app.expected)

def lab_click(app,event):
    if app.phase != 'search':
        return
    col = int((event.x-220)//75); row = int((event.y-20)//50)
    if 0 <= col < 6 and 0 <= row < 6 and (event.x-220)%75 <= 65 and (event.y-20)%50 <= 42:
        lab_finish(app,row*6+col==app.target)

def lab_plot(app):
    c = app.Trend; c.delete('all'); data = app.results[-20:]
    scale = max([r['response_ms'] for r in data]+[1])
    for i,record in enumerate(data):
        x = 20+i*44; height = record['response_ms']/scale*110
        c.create_rectangle(x,135-height,x+30,135,fill='#3c9970' if record['correct'] else '#c35c62',outline='')
        c.create_text(x+15,150,text=str(len(app.results)-len(data)+i+1))
    correct = sum(r['correct'] for r in app.results)
    app.Summary.configure(text=f'Session trials: {len(app.results)} | Correct: {correct} | Green=correct, red=incorrect. Bar height=response time; modes are not directly comparable.')

def lab_export(app):
    path = filedialog.asksaveasfilename(parent=app.Form1,defaultextension='.csv',filetypes=[('CSV','*.csv')])
    if not path:
        return
    try:
        with open(path,'w',newline='',encoding='utf-8') as stream:
            writer = csv.DictWriter(stream,fieldnames=['timestamp','mode','level','correct','response_ms']); writer.writeheader(); writer.writerows(app.results)
    except OSError as exc:
        messagebox.showerror('Lab',str(exc),parent=app.Form1)

def lab_close(app):
    if app.results and not messagebox.askyesno('Lab','Close? Session results will be lost unless exported.',parent=app.Form1):
        return
    lab_cancel(app); app.root.destroy()
